// Route contract for this endpoint (read by wf.gateway.auth).
const route = {"method": "POST", "template": "/v1/flatmates/:user_id/explanation", "require_user": true, "idempotent": true, "required_consents": ["terms", "privacy"], "roles": []};
const item = $input.first();
return [{ json: { ...item.json, t0: Date.now(), route }, binary: item.binary }];

// Platform endpoints (n8n/build_platform.py) > "Validate"
// One shared validator: build_platform.py writes the endpoint's spec into SPEC below at build time.
// spec = {params: {name: 'uuid' | 'int'}, query: {name: rule}, body: JSON schema | null, rules: [...]}
// rule = {type: 'int', min, max} | {type: 'bool'} | {type: 'enum', values} | {type: 'string', max, pattern} | {type: 'uuid'} | {type: 'date'}
// Output: {ok, gw, input: {params, query, body}} for the database call, or a 404/422 rejection.
// Small JSON Schema validator for LLM outputs and request bodies (spec 9.2: validate every
// output against its schema). n8n Code nodes cannot load packages (no require), so this
// covers the subset the schemas in prompts/schemas/ use: type (one or a list, including
// "null" and "integer"), enum, const, required, properties, additionalProperties (boolean
// or schema), items, minItems, maxItems, minimum, maximum, minLength, maxLength, pattern.
// Anything else in a schema is ignored. Cross-checked against the Python jsonschema package
// in tests/unit/test_prompts.py.
// Returns a list of errors [{path, issue, ...}]; empty when the value is valid.

function typeOf(v) {
  if (v === null) return 'null';
  if (Array.isArray(v)) return 'array';
  if (typeof v === 'number') return Number.isInteger(v) ? 'integer' : 'number';
  return typeof v;            // string, boolean, object
}

function typeMatches(t, v) {
  const actual = typeOf(v);
  if (t === actual) return true;
  if (t === 'number' && actual === 'integer') return true;
  return false;
}

function validate(schema, value, path = '$', errors = []) {
  if (!schema || typeof schema !== 'object') return errors;
  if (schema.type !== undefined) {
    const types = Array.isArray(schema.type) ? schema.type : [schema.type];
    if (!types.some((t) => typeMatches(t, value))) {
      errors.push({ path, issue: 'type', expected: types.join('|'), got: typeOf(value) });
      return errors;
    }
  }
  if (schema.enum !== undefined && !schema.enum.some((e) => e === value)) {
    errors.push({ path, issue: 'enum', allowed: schema.enum });
  }
  if (schema.const !== undefined && schema.const !== value) errors.push({ path, issue: 'const' });
  const t = typeOf(value);
  if (t === 'string') {
    // length in code points, as JSON Schema counts it
    const len = Array.from(value).length;
    if (schema.minLength !== undefined && len < schema.minLength) errors.push({ path, issue: 'minLength', min: schema.minLength });
    if (schema.maxLength !== undefined && len > schema.maxLength) errors.push({ path, issue: 'maxLength', max: schema.maxLength });
    if (schema.pattern !== undefined && !new RegExp(schema.pattern, 'u').test(value)) errors.push({ path, issue: 'pattern' });
  }
  if (t === 'integer' || t === 'number') {
    if (schema.minimum !== undefined && value < schema.minimum) errors.push({ path, issue: 'minimum', min: schema.minimum });
    if (schema.maximum !== undefined && value > schema.maximum) errors.push({ path, issue: 'maximum', max: schema.maximum });
  }
  if (t === 'array') {
    if (schema.minItems !== undefined && value.length < schema.minItems) errors.push({ path, issue: 'minItems', min: schema.minItems });
    if (schema.maxItems !== undefined && value.length > schema.maxItems) errors.push({ path, issue: 'maxItems', max: schema.maxItems });
    if (schema.items) value.forEach((v, i) => validate(schema.items, v, `${path}[${i}]`, errors));
  }
  if (t === 'object') {
    for (const k of schema.required || []) {
      if (!Object.prototype.hasOwnProperty.call(value, k)) errors.push({ path: `${path}.${k}`, issue: 'required' });
    }
    const props = schema.properties || {};
    for (const [k, v] of Object.entries(value)) {
      if (Object.prototype.hasOwnProperty.call(props, k)) validate(props[k], v, `${path}.${k}`, errors);
      else if (schema.additionalProperties === false) errors.push({ path: `${path}.${k}`, issue: 'additional_property' });
      else if (schema.additionalProperties && typeof schema.additionalProperties === 'object') {
        validate(schema.additionalProperties, v, `${path}.${k}`, errors);
      }
    }
  }
  return errors;
}

// One line per error, for retry prompts and logs.
function describe(errors, max = 8) {
  return errors.slice(0, max).map((e) => {
    switch (e.issue) {
      case 'type': return `${e.path}: expected ${e.expected}, got ${e.got}`;
      case 'enum': return `${e.path}: must be one of ${JSON.stringify(e.allowed)}`;
      case 'required': return `${e.path}: missing`;
      case 'additional_property': return `${e.path}: not allowed`;
      default: return `${e.path}: ${e.issue}`;
    }
  }).join('; ');
}

if (typeof module !== 'undefined') module.exports = { validate, describe, typeOf };

const SPEC = {"params": {"user_id": "uuid"}, "body": {"type": "object", "additionalProperties": false, "properties": {"language": {"type": "string", "enum": ["fr", "en", "ar"]}}, "required": []}};
const gw = $input.first().json;
const ctx = gw.ctx || {};
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const reject = (status, code, message, details = []) => [{ json: { ok: false, gw, status, error: { code, message, details } } }];

// Path parameters: a malformed id is a resource that does not exist (404), as in the /v1 GET-by-id endpoints.
const params = {};
for (const [k, t] of Object.entries(SPEC.params || {})) {
  const v = String((ctx.params || {})[k] ?? '');
  if (t === 'uuid' && !UUID.test(v)) return reject(404, 'NOT_FOUND', 'Not found');
  if (t === 'int' && !/^\d{1,18}$/.test(v)) return reject(404, 'NOT_FOUND', 'Not found');
  params[k] = t === 'uuid' ? v.toLowerCase() : v;
}

const details = [];
const query = {};
const q = ctx.query || {};
const rules = SPEC.query || {};
for (const k of Object.keys(q)) if (!(k in rules)) details.push({ field: k, issue: 'unknown_parameter' });
for (const [k, r] of Object.entries(rules)) {
  if (q[k] === undefined || q[k] === null || String(q[k]) === '') continue;
  if (Array.isArray(q[k])) { details.push({ field: k, issue: 'repeated_parameter' }); continue; }
  const v = String(q[k]).trim();
  if (r.type === 'int') {
    if (!/^-?\d{1,18}$/.test(v) || (r.min !== undefined && Number(v) < r.min) || (r.max !== undefined && Number(v) > r.max)) {
      details.push({ field: k, issue: 'out_of_range', min: r.min, max: r.max });
    } else query[k] = Number(v);
  } else if (r.type === 'bool') {
    if (!['true', 'false'].includes(v)) details.push({ field: k, issue: 'must_be_true_or_false' }); else query[k] = v === 'true';
  } else if (r.type === 'enum') {
    if (!r.values.includes(v)) details.push({ field: k, issue: 'not_allowed', allowed: r.values }); else query[k] = v;
  } else if (r.type === 'uuid') {
    if (!UUID.test(v)) details.push({ field: k, issue: 'invalid_format' }); else query[k] = v.toLowerCase();
  } else if (r.type === 'date') {
    if (!/^\d{4}-\d{2}-\d{2}$/.test(v) || isNaN(Date.parse(v + 'T00:00:00Z'))) details.push({ field: k, issue: 'invalid_date' }); else query[k] = v;
  } else {
    if (Array.from(v).length > (r.max || 200)) details.push({ field: k, issue: 'too_long', max: r.max || 200 });
    else if (r.pattern && !new RegExp(r.pattern).test(v)) details.push({ field: k, issue: 'invalid_format' });
    else query[k] = v;
  }
}

let body = null;
if (SPEC.body) {
  body = ctx.body || {};
  for (const e of validate(SPEC.body, body)) details.push({ field: e.path.replace(/^\$\.?/, '') || 'body', issue: e.issue });
  // one of these fields must be given (JSON Schema's anyOf/required, which schema_lite does not cover)
  if (SPEC.require_any && !SPEC.require_any.some((f) => body[f] !== undefined && body[f] !== null)) {
    details.push({ field: SPEC.require_any.join('|'), issue: 'one_required' });
  }
}
if (details.length) return reject(422, 'VALIDATION_FAILED', 'Request is invalid', details);
return [{ json: { ok: true, gw, input: { params, query, body: body || {}, lang: ctx.lang || null } } }];

// wf.api.flatmate_explain > "Plan" (platform P12, D-115): the score and factor states of social.compatibility for the
// pair (never the other person's answers). With the setting on and something known, one P12_match_explainer call
// writes the sentence; otherwise the sentence written by code is the answer.
// Flatmate matching helpers (platform P12, D-115, from Yosr's roommate matching). Plain code, no model:
//  - checkProposal: the profile agent's proposal -> the fields the platform knows, with valid values only;
//  - supportedByText: an amount, a place or a date the person did not write is dropped (the model cannot invent them);
//  - explainFactors / codeSentence / checkSentence: the match explanation from the factor states of
//    social.compatibility, the sentence written by code, and the check of the model's sentence.

const LIFESTYLE = { smoking: ['yes', 'no'], pets: ['yes', 'no'], guests: ['yes', 'no'], quiet_hours: ['yes', 'no'],
  schedule: ['early', 'late', 'irregular'], cleanliness: ['high', 'medium', 'relaxed'] };
const SEEKING = ['room', 'flatmate', 'both'];
const LANGS = ['ar', 'aeb', 'fr', 'en', 'de', 'es', 'it'];
const plain = (s) => String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();

/** values: an object or a JSON string. Returns {values, errors}: values hold only known fields with valid values. */
function checkProposal(values) {
  let v = values;
  if (typeof v === 'string') { try { v = JSON.parse(v); } catch (e) { return { values: {}, errors: [{ field: 'values', issue: 'not_json' }] }; } }
  if (!v || typeof v !== 'object' || Array.isArray(v)) return { values: {}, errors: [{ field: 'values', issue: 'not_an_object' }] };
  const out = {};
  const errors = [];
  const ls = v.lifestyle && typeof v.lifestyle === 'object' ? v.lifestyle : {};
  for (const [k, x] of Object.entries(ls)) {
    if (!LIFESTYLE[k]) { errors.push({ field: `lifestyle.${k}`, issue: 'unknown' }); continue; }
    const val = String(x).toLowerCase();
    if (!LIFESTYLE[k].includes(val)) { errors.push({ field: `lifestyle.${k}`, issue: 'one_of', allowed: LIFESTYLE[k] }); continue; }
    (out.lifestyle = out.lifestyle || {})[k] = val;
  }
  for (const k of ['budget_min', 'budget_max']) {
    if (v[k] === undefined || v[k] === null || v[k] === '') continue;
    const n = Number(v[k]);
    if (!Number.isFinite(n) || n <= 0 || n > 1e6) errors.push({ field: k, issue: 'positive_number' }); else out[k] = Math.round(n * 1000) / 1000;
  }
  if (out.budget_min !== undefined && out.budget_max !== undefined && out.budget_min > out.budget_max) {
    errors.push({ field: 'budget_min', issue: 'more_than_max' });
    delete out.budget_min;
  }
  if (v.areas !== undefined) {
    const a = (Array.isArray(v.areas) ? v.areas : [v.areas]).map((x) => String(x || '').trim()).filter((x) => x && x.length <= 60);
    if (a.length) out.areas = [...new Set(a)].slice(0, 5); else errors.push({ field: 'areas', issue: 'empty' });
  }
  if (v.move_in_from !== undefined && v.move_in_from !== null && v.move_in_from !== '') {
    const d = String(v.move_in_from);
    if (/^\d{4}-\d{2}-\d{2}$/.test(d) && !Number.isNaN(Date.parse(`${d}T00:00:00Z`))) out.move_in_from = d;
    else errors.push({ field: 'move_in_from', issue: 'date_yyyy_mm_dd' });
  }
  if (v.headline !== undefined && String(v.headline).trim()) out.headline = String(v.headline).replace(/\s+/g, ' ').trim().slice(0, 80);
  if (v.seeking !== undefined) {
    if (SEEKING.includes(String(v.seeking))) out.seeking = String(v.seeking); else errors.push({ field: 'seeking', issue: 'one_of', allowed: SEEKING });
  }
  if (v.languages !== undefined) {
    const l = (Array.isArray(v.languages) ? v.languages : []).map((x) => String(x).toLowerCase()).filter((x) => LANGS.includes(x));
    if (l.length) out.languages = [...new Set(l)];
  }
  if (v.visible !== undefined) out.visible = v.visible === true || v.visible === 'true';
  return { values: out, errors };
}

/** Numbers written in a text (1200, 1 200, 1.200, 1,200, 450.000 for Tunisian dinars). */
function numbersIn(text) {
  const out = new Set();
  for (const m of String(text || '').matchAll(/\d(?:[\d.,]|\s(?=\d{3}\b))*/g)) {
    const s = m[0].replace(/[.,]+$/, '').replace(/\s/g, '');
    for (const c of [s.replace(/[.,]/g, ''), s.replace(/,/g, '.'), s.replace(/\./g, '').replace(',', '.'), s.replace(/,/g, '')]) {
      const n = Number(c);
      if (Number.isFinite(n)) out.add(n);
    }
    if (/^\d{1,4}\.000$/.test(s)) out.add(Number(s.split('.')[0]));          // 450.000 DT = 450 dinars
  }
  return out;
}

/** Keeps a budget, place or date only when the person wrote it; returns {values, dropped}. texts: what the person wrote
 *  in this conversation. Lifestyle answers, the headline and seeking are the model's reading and are shown for checking. */
function supportedByText(values, texts) {
  const all = (texts || []).join('\n');
  const nums = numbersIn(all);
  const low = plain(all);
  const out = JSON.parse(JSON.stringify(values || {}));
  const dropped = [];
  for (const k of ['budget_min', 'budget_max']) {
    if (out[k] !== undefined && ![...nums].some((n) => Math.abs(n - out[k]) < 0.005)) { dropped.push({ field: k, why: 'not_in_text' }); delete out[k]; }
  }
  if (out.areas) {
    const kept = out.areas.filter((a) => low.includes(plain(a)));
    for (const a of out.areas) if (!kept.includes(a)) dropped.push({ field: 'areas', value: a, why: 'not_in_text' });
    if (kept.length) out.areas = kept; else delete out.areas;
  }
  if (out.move_in_from) {
    const [y, m, d] = out.move_in_from.split('-').map(Number);
    const months = ['janv', 'fevr', 'mars', 'avr', 'mai', 'juin', 'juil', 'aout', 'sept', 'oct', 'nov', 'dec'];
    const monthsEn = ['jan', 'feb', 'mar', 'apr', 'may', 'jun', 'jul', 'aug', 'sep', 'oct', 'nov', 'dec'];
    const said = low.includes(out.move_in_from) || nums.has(d) || low.includes(months[m - 1]) || low.includes(monthsEn[m - 1])
      || new RegExp(`\\b${m}[/.-]${y}\\b|\\b${d}[/.-]${m}\\b`).test(low);
    if (!said) { dropped.push({ field: 'move_in_from', why: 'not_in_text' }); delete out.move_in_from; }
  }
  return { values: out, dropped };
}

// ---- match explanation -------------------------------------------------------------------------------------------------
const TOPIC = {
  fr: { schedule: 'les horaires', cleanliness: 'la propreté', smoking: 'le tabac', pets: 'les animaux', guests: 'les invités',
        quiet_hours: 'le calme', languages: 'les langues', budget: 'le budget', move_in: "la date d'arrivée", distance: 'le quartier' },
  en: { schedule: 'schedule', cleanliness: 'tidiness', smoking: 'smoking', pets: 'pets', guests: 'guests', quiet_hours: 'quiet hours',
        languages: 'languages', budget: 'budget', move_in: 'move-in date', distance: 'area' },
  ar: { schedule: 'المواعيد', cleanliness: 'النظافة', smoking: 'التدخين', pets: 'الحيوانات', guests: 'الضيوف', quiet_hours: 'الهدوء',
        languages: 'اللغات', budget: 'الميزانية', move_in: 'تاريخ الانتقال', distance: 'الحي' },
};
const WORDS = {
  fr: { match: 'Vous vous accordez sur', differs: 'À discuter', unknown: 'Pas encore dit', none: 'Pas assez de réponses pour dire si vous vous accordez.' },
  en: { match: 'You agree on', differs: 'To talk about', unknown: 'Not said yet', none: 'Not enough answers yet to say how well you match.' },
  ar: { match: 'تتفقان في', differs: 'للنقاش', unknown: 'لم يُذكر بعد', none: 'لا توجد إجابات كافية بعد.' },
};

/** The factor states as words for the prompt: "smoking: match; pets: differs; schedule: unknown". */
function explainFactors(compat, lang) {
  const T = TOPIC[lang] || TOPIC.fr;
  return ((compat && compat.factors) || []).map((f) => `${T[f.factor] || f.factor}: ${f.state}`).join('; ');
}

/** The sentence written by code, used when the model is off or its sentence fails the check. */
function codeSentence(compat, lang) {
  const T = TOPIC[lang] || TOPIC.fr;
  const W = WORDS[lang] || WORDS.fr;
  const by = (st) => ((compat && compat.factors) || []).filter((f) => f.state === st).map((f) => T[f.factor] || f.factor);
  const sep = lang === 'fr' ? ' : ' : ': ';
  const parts = [];
  if (by('match').length) parts.push(`${W.match}${sep}${by('match').join(', ')}.`);
  if (by('differs').length) parts.push(`${W.differs}${sep}${by('differs').join(', ')}.`);
  if (!parts.length) return W.none;
  return parts.join(' ');
}

/** The model's sentence is kept only if it is short, adds no number but the score, and names no topic that is not in the
 *  factors given. Returns {ok, why}. */
function checkSentence(sentence, compat, lang) {
  const s = String(sentence || '').trim();
  if (s.length < 10 || s.length > 300) return { ok: false, why: 'length' };
  const score = compat && compat.score;
  for (const n of numbersIn(s)) if (n !== score && n !== 100) return { ok: false, why: 'number_not_given' };
  const known = new Set(((compat && compat.factors) || []).map((f) => f.factor));
  const T = TOPIC[lang] || TOPIC.fr;
  for (const [k, word] of Object.entries(T)) {
    if (!known.has(k) && plain(s).includes(plain(word))) return { ok: false, why: `topic_not_given:${k}` };
  }
  return { ok: true, why: null };
}

if (typeof module !== 'undefined') {
  module.exports = { checkProposal, supportedByText, numbersIn, explainFactors, codeSentence, checkSentence, LIFESTYLE };
}

const v = $('Validate').first().json;
const r = ($input.first().json || {}).r || null;
const gw = v.gw;
if (!r || r.error) {
  return [{ json: { model: false, done: true, ok: false, gw, status: r ? r.status : 500,
    error: r ? { ...r.error, details: r.error.details || [] } : { code: 'INTERNAL', message: 'Internal error', details: [] } } }];
}
const lang = ['fr', 'en', 'ar'].includes((v.input.body || {}).language) ? v.input.body.language : 'fr';
const c = r.data.compatibility || {};
const base = { gw, lang, compat: c, other: r.data.other, code: codeSentence(c, lang) };
if (!r.data.enabled || c.score === null || c.score === undefined) return [{ json: { ...base, model: false } }];
return [{ json: { ...base, model: true, llm: { prompt: 'P12_match_explainer', vars: { name: (r.data.other || {}).display_name || '-',
  score: String(c.score), factors: explainFactors(c, lang), language: { fr: 'French', en: 'English', ar: 'Arabic' }[lang] },
  meta: { user_id: gw.ctx.user_id } } } }];

